package com.performance.io.annotation;

import java.lang.annotation.*;
import java.lang.reflect.Method;
import java.nio.file.Path;

/**
 * Meta-annotations defining a custom runtime annotation.
 * This annotation is used to enforce directory path validation within an NIO file-watcher service.
 */
@Documented
@Target({ElementType.METHOD, ElementType.PARAMETER})
@Retention(RetentionPolicy.RUNTIME)
@Inherited
public @interface ValidatedPath {
    boolean mustExist() default true;
    boolean requireWritable() default false;
    String errorMessage() default "Invalid path configuration detected.";
}

/**
 * Runtime processor that leverages reflection to inspect the custom annotation.
 */
class PathValidator {
    public static void validateMethodParameters(Object instance, Method method, Object[] args) throws Exception {
        java.lang.annotation.Annotation[][] parameterAnnotations = method.getParameterAnnotations();
        for (int i = 0; i < parameterAnnotations.length; i++) {
            for (Annotation annotation : parameterAnnotations[i]) {
                if (annotation instanceof ValidatedPath) {
                    ValidatedPath validatedPath = (ValidatedPath) annotation;
                    Path path = (Path) args[i];

                    if (validatedPath.mustExist() && !path.toFile().exists()) {
                        throw new IllegalArgumentException(validatedPath.errorMessage() + " Path does not exist: " + path);
                    }
                    if (validatedPath.requireWritable() && !path.toFile().canWrite()) {
                        throw new SecurityException(validatedPath.errorMessage() + " Path is not writable: " + path);
                    }
                }
            }
        }
    }
}
